{
  "implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    last = attempts[-1] if attempts else None
    if last is None:
        return {'decision': 'start', 'memory_append': None, 'next_attempt': 0}
    if last['success']:
        return {'decision': 'finalize', 'memory_append': None, 'next_attempt': -1}
    if len(attempts) >= max_attempts:
        return {'decision': 'exhausted', 'memory_append': {'reflection': last['reflection'], 'signature': last['failure_signature']}, 'next_attempt': -1}
    return {'decision': 'retry', 'memory_append': {'reflection': last['reflection'], 'signature': last['failure_signature']}, 'next_attempt': len(attempts)}"
}
